public void printList(List<?> list) {
    for (Object elem : list) {
        System.out.println(elem + " ");
    }
}
// works on a List<Integer>, a List<String>, anything

public double sumOfList(List<? extends Number> list) {
    double s = 0.0;
    for (Number n : list) {
        s += n.doubleValue();
    }
    return s;
}
// sumOfList(List.of(1, 2, 3)) sums to 6.0
// sumOfList(List.of(1.2, 2.3, 3.5)) sums to 7.0

public void addNumbers(List<? super Integer> list) {
    for (int i = 1; i <= 10; i++) {
        list.add(i);
    }
}
